"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/shared-detail.css";
import { ArrowLeft, X } from "@phosphor-icons/react";
import { AnimatePresence, LayoutGroup, motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import type { BehaviorContract } from "../../lib/behavior-contract";
import { cn } from "../../lib/cn";
import { IconButton } from "./icon-button";
import { getSharedDetailMotionPreset, selectedSharedDetailMotionPreset, type SharedDetailMotionPresetId } from "./shared-detail-motion";

export {
  getSharedDetailMotionPreset,
  selectedSharedDetailMotionPreset,
  sharedDetailMotionPresets,
  type SharedDetailMotionPreset,
  type SharedDetailMotionPresetId,
} from "./shared-detail-motion";

export const sharedDetailContract: BehaviorContract = {
  input: ["Row click", "Enter on row", "Close button", "Escape"],
  origin: "The selected row title is the visual and focus origin for the detail surface.",
  enter: "Pointer activation uses title continuity and a 180ms panel reveal; keyboard activation is direct.",
  active: "The non-modal detail is a labelled region; focus enters the region without triggering a tooltip.",
  exit: "The panel contracts toward the selected row before the row trigger regains focus.",
  interruption: "A second selection retargets the shared element without stacking panels.",
  keyboard: ["Enter/Space: open", "Escape: close", "Tab: navigate detail controls"],
  reducedMotion: "A 120ms opacity transition replaces travel and shared-layout movement; focus origin remains explicit.",
};

const reducedMotionTransition = { duration: 0.12, ease: [0.23, 1, 0.32, 1] as [number, number, number, number] };

export type SharedDetailItem = {
  id: string;
  title: string;
  meta: string;
  description: string;
  status?: string;
};

export type SharedDetailProps = {
  items: readonly SharedDetailItem[];
  className?: string;
  selectedId?: string | null;
  defaultSelectedId?: string;
  onSelectedIdChange?: (id: string | null) => void;
  motionPreset?: SharedDetailMotionPresetId;
  focusOnOpen?: boolean;
  regionLabel?: string;
  renderDetail?: (item: SharedDetailItem) => ReactNode;
};

export function SharedDetail({
  items,
  className,
  selectedId: selectedIdProp,
  defaultSelectedId,
  onSelectedIdChange,
  motionPreset = selectedSharedDetailMotionPreset,
  focusOnOpen = true,
  regionLabel,
  renderDetail,
}: SharedDetailProps) {
  const [uncontrolledSelectedId, setUncontrolledSelectedId] = useState<string | null>(defaultSelectedId ?? null);
  const [keyboardInvoked, setKeyboardInvoked] = useState(false);
  const selectedId = selectedIdProp === undefined ? uncontrolledSelectedId : selectedIdProp;
  const selected = items.find((item) => item.id === selectedId);
  const originRef = useRef<HTMLButtonElement | null>(null);
  const panelRef = useRef<HTMLElement | null>(null);
  const interactedRef = useRef(false);
  const reduceMotion = useReducedMotion();
  const layoutGroupId = useId();
  const panelId = (itemId: string) => `${layoutGroupId}-detail-panel-${itemId}`;
  const titleId = (itemId: string) => `${layoutGroupId}-detail-title-${itemId}`;
  const preset = getSharedDetailMotionPreset(motionPreset);
  const motionMode = keyboardInvoked ? "direct" : reduceMotion ? "reduced" : "full";
  const spatialMotion = motionMode === "full";
  const panelInitial = motionMode === "direct" ? false : motionMode === "reduced" ? { opacity: 0 } : preset.panelInitial;
  const panelExit = motionMode === "full" ? preset.panelExit : { opacity: 0 };
  const panelTransition = motionMode === "direct" ? { duration: 0 } : motionMode === "reduced" ? reducedMotionTransition : preset.panelTransition;
  const contentInitial = motionMode === "direct" ? false : motionMode === "reduced" ? { opacity: 0 } : preset.contentInitial;
  const contentExit = motionMode === "full" ? preset.contentExit : { opacity: 0 };
  const contentTransition = motionMode === "direct" ? { duration: 0 } : motionMode === "reduced" ? reducedMotionTransition : preset.contentTransition;

  const setSelectedId = (id: string | null) => {
    if (selectedIdProp === undefined) setUncontrolledSelectedId(id);
    onSelectedIdChange?.(id);
  };

  const close = () => {
    setSelectedId(null);
    requestAnimationFrame(() => originRef.current?.focus({ preventScroll: true }));
  };

  useEffect(() => {
    if (!selected) return;
    if (focusOnOpen && interactedRef.current) requestAnimationFrame(() => panelRef.current?.focus({ preventScroll: true }));
    const onKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape" && !event.defaultPrevented) { event.preventDefault(); close(); }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [selected]);

  return (
    <LayoutGroup id={layoutGroupId}>
      <div className={cn("whatiuse-shared-detail", className)} data-open={Boolean(selected) || undefined} data-motion-preset={motionPreset} data-motion-mode={motionMode}>
        <div className="whatiuse-shared-detail__list" aria-label="Objects">
          {items.map((item) => (
            <button
              type="button"
              key={item.id}
              className="whatiuse-shared-detail__row"
              aria-expanded={selectedId === item.id}
              aria-controls={selectedId === item.id ? panelId(item.id) : undefined}
              onClick={(event) => {
                interactedRef.current = true;
                originRef.current = event.currentTarget;
                setKeyboardInvoked(event.detail === 0);
                setSelectedId(item.id);
              }}
            >
              <span className="whatiuse-shared-detail__dot" aria-hidden="true" />
              <span className="whatiuse-shared-detail__row-copy" data-title={item.title}>
                <motion.span layout={spatialMotion ? "position" : false} layoutId={spatialMotion ? titleId(item.id) : undefined} transition={spatialMotion ? preset.titleTransition : { duration: 0 }}>{item.title}</motion.span>
                <small>{item.meta}</small>
              </span>
              {item.status && <span className="whatiuse-shared-detail__status">{item.status}</span>}
            </button>
          ))}
        </div>
        <AnimatePresence initial={false}>
          {selected && (
            <motion.aside
              ref={panelRef}
              id={panelId(selected.id)}
              className="whatiuse-shared-detail__panel"
              role="region"
              tabIndex={-1}
              aria-label={regionLabel}
              aria-labelledby={regionLabel ? undefined : titleId(selected.id)}
              initial={panelInitial}
              animate={{ opacity: 1, transform: "translateX(0px) scale(1)", clipPath: "inset(0 0 0 0)", filter: "blur(0px)" }}
              exit={panelExit}
              transition={panelTransition}
            >
              <div className="whatiuse-shared-detail__toolbar">
                <IconButton className="whatiuse-shared-detail__back" variant="ghost" size="small" aria-label="Back to list" tooltip="Back" onClick={close}><ArrowLeft /></IconButton>
                <IconButton variant="ghost" size="small" aria-label="Close detail" tooltip="Close" onClick={close}><X /></IconButton>
              </div>
              <AnimatePresence mode="popLayout" initial={false}>
                <motion.div
                  key={selected.id}
                  className="whatiuse-shared-detail__content"
                  initial={contentInitial}
                  animate={{ opacity: 1, transform: "translateY(0px)", filter: "blur(0px)" }}
                  exit={contentExit}
                  transition={contentTransition}
                >
                  <motion.h3 layout={spatialMotion ? "position" : false} id={titleId(selected.id)} layoutId={spatialMotion ? titleId(selected.id) : undefined} transition={spatialMotion ? preset.titleTransition : { duration: 0 }}>{selected.title}</motion.h3>
                  <div className="whatiuse-shared-detail__meta">{selected.meta}</div>
                  {renderDetail ? renderDetail(selected) : <><p>{selected.description}</p><dl><div><dt>Status</dt><dd>{selected.status ?? "Open"}</dd></div><div><dt>Interaction</dt><dd>Shared detail</dd></div></dl></>}
                </motion.div>
              </AnimatePresence>
            </motion.aside>
          )}
        </AnimatePresence>
      </div>
    </LayoutGroup>
  );
}

export type SharedDetailMotionPresetId =
  | "continuity"
  | "quiet"
  | "soft-scale"
  | "spring"
  | "reveal"
  | "crossfade"
  | "stagger"
  | "direct";

type Bezier = [number, number, number, number];

export type SharedDetailMotionPreset = {
  id: SharedDetailMotionPresetId;
  label: string;
  description: string;
  panelInitial: Record<string, string | number>;
  panelExit: Record<string, string | number>;
  panelTransition: { duration?: number; ease?: Bezier; type?: "spring"; bounce?: number };
  contentInitial: Record<string, string | number>;
  contentExit: Record<string, string | number>;
  contentTransition: { duration: number; ease: Bezier; delay?: number };
  titleTransition: { duration?: number; ease?: Bezier; type?: "spring"; bounce?: number };
};

const easeOut: Bezier = [0.23, 1, 0.32, 1];
const easeInOut: Bezier = [0.77, 0, 0.175, 1];
const fluid: Bezier = [0.32, 0.72, 0, 1];

export const sharedDetailMotionPresets: readonly SharedDetailMotionPreset[] = [
  {
    id: "continuity",
    label: "Continuity",
    description: "Selected. Crisp panel travel with a softer shared-title handoff.",
    panelInitial: { opacity: 0, transform: "translateX(8px)" },
    panelExit: { opacity: 0, transform: "translateX(5px)" },
    panelTransition: { duration: 0.18, ease: fluid },
    contentInitial: { opacity: 0, transform: "translateY(2px)" },
    contentExit: { opacity: 0 },
    contentTransition: { duration: 0.14, ease: easeOut, delay: 0.02 },
    titleTransition: { type: "spring", duration: 0.26, bounce: 0.04 },
  },
  {
    id: "quiet",
    label: "Quiet slide",
    description: "Short travel and no decorative softness.",
    panelInitial: { opacity: 0, transform: "translateX(8px)" },
    panelExit: { opacity: 0, transform: "translateX(6px)" },
    panelTransition: { duration: 0.16, ease: easeOut },
    contentInitial: { opacity: 0 },
    contentExit: { opacity: 0 },
    contentTransition: { duration: 0.12, ease: easeOut },
    titleTransition: { duration: 0.18, ease: easeInOut },
  },
  {
    id: "soft-scale",
    label: "Soft scale",
    description: "A compact reveal that feels slightly more dimensional.",
    panelInitial: { opacity: 0, transform: "translateX(8px) scale(0.99)" },
    panelExit: { opacity: 0, transform: "translateX(5px) scale(0.995)" },
    panelTransition: { duration: 0.2, ease: easeOut },
    contentInitial: { opacity: 0, transform: "translateY(3px)" },
    contentExit: { opacity: 0 },
    contentTransition: { duration: 0.15, ease: easeOut, delay: 0.03 },
    titleTransition: { duration: 0.22, ease: easeInOut },
  },
  {
    id: "spring",
    label: "Spring",
    description: "Interruptible movement with restrained physicality.",
    panelInitial: { opacity: 0, transform: "translateX(16px)" },
    panelExit: { opacity: 0, transform: "translateX(10px)" },
    panelTransition: { type: "spring", duration: 0.28, bounce: 0.08 },
    contentInitial: { opacity: 0, transform: "translateY(5px)" },
    contentExit: { opacity: 0, transform: "translateY(-3px)" },
    contentTransition: { duration: 0.17, ease: easeOut, delay: 0.035 },
    titleTransition: { type: "spring", duration: 0.28, bounce: 0.1 },
  },
  {
    id: "reveal",
    label: "Edge reveal",
    description: "The detail surface is clipped from its attachment edge.",
    panelInitial: { opacity: 0.65, clipPath: "inset(0 0 0 10%)", transform: "translateX(6px)" },
    panelExit: { opacity: 0, clipPath: "inset(0 0 0 6%)", transform: "translateX(5px)" },
    panelTransition: { duration: 0.21, ease: easeOut },
    contentInitial: { opacity: 0 },
    contentExit: { opacity: 0 },
    contentTransition: { duration: 0.14, ease: easeOut, delay: 0.04 },
    titleTransition: { duration: 0.22, ease: easeInOut },
  },
  {
    id: "crossfade",
    label: "Crossfade",
    description: "Motion-minimal study for maximum calm.",
    panelInitial: { opacity: 0 },
    panelExit: { opacity: 0 },
    panelTransition: { duration: 0.17, ease: easeOut },
    contentInitial: { opacity: 0, filter: "blur(1px)" },
    contentExit: { opacity: 0, filter: "blur(1px)" },
    contentTransition: { duration: 0.15, ease: easeOut },
    titleTransition: { duration: 0.18, ease: easeInOut },
  },
  {
    id: "stagger",
    label: "Stagger",
    description: "Panel arrives first, then its detail content follows.",
    panelInitial: { opacity: 0, transform: "translateX(12px)" },
    panelExit: { opacity: 0, transform: "translateX(7px)" },
    panelTransition: { duration: 0.2, ease: fluid },
    contentInitial: { opacity: 0, transform: "translateY(6px)" },
    contentExit: { opacity: 0, transform: "translateY(-2px)" },
    contentTransition: { duration: 0.18, ease: easeOut, delay: 0.065 },
    titleTransition: { duration: 0.24, ease: easeInOut },
  },
  {
    id: "direct",
    label: "Direct",
    description: "Fastest study for keyboard-heavy repetition.",
    panelInitial: { opacity: 0, transform: "translateX(4px)" },
    panelExit: { opacity: 0 },
    panelTransition: { duration: 0.1, ease: easeOut },
    contentInitial: { opacity: 0 },
    contentExit: { opacity: 0 },
    contentTransition: { duration: 0.08, ease: easeOut },
    titleTransition: { duration: 0.11, ease: easeInOut },
  },
] as const;

export const selectedSharedDetailMotionPreset = "continuity" satisfies SharedDetailMotionPresetId;

export function getSharedDetailMotionPreset(id: SharedDetailMotionPresetId) {
  return sharedDetailMotionPresets.find((preset) => preset.id === id) ?? sharedDetailMotionPresets[0];
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-shared-detail { position: relative; display: grid; grid-template-columns: minmax(0, 1fr); min-height: 252px; overflow: hidden; border: 1px solid var(--whatiuse-border-subtle); border-radius: var(--whatiuse-radius-container); background: var(--whatiuse-surface); }

.whatiuse-shared-detail[data-open] { grid-template-columns: minmax(230px, 0.9fr) minmax(260px, 1.1fr); }

.whatiuse-shared-detail__list { min-width: 0; padding: 4px; }

.whatiuse-shared-detail__row { display: grid; grid-template-columns: 14px minmax(0, 1fr) auto; width: 100%; min-height: 52px; align-items: center; gap: 7px; padding: 5px 8px; border: 0; border-radius: calc(var(--whatiuse-radius-control) - 1px); background: transparent; text-align: left; cursor: pointer; transition: background-color var(--whatiuse-hover-duration), color var(--whatiuse-hover-duration); }

.whatiuse-shared-detail__row:hover,
.whatiuse-shared-detail__row[aria-expanded="true"] { background: var(--whatiuse-hover); }

.whatiuse-shared-detail__row:focus-visible { position: relative; z-index: 1; }

.whatiuse-shared-detail__dot { width: 7px; height: 7px; border: 1px solid var(--whatiuse-fg-default); border-radius: 2px; }

.whatiuse-shared-detail__row-copy { position: relative; display: grid; gap: 2px; min-width: 0; }

.whatiuse-shared-detail__row[aria-expanded="true"] .whatiuse-shared-detail__row-copy::before { position: absolute; z-index: 1; top: 0; right: 0; left: 0; overflow: hidden; background: var(--whatiuse-hover); color: var(--whatiuse-ink); font-size: 13.5px; font-weight: 520; line-height: 19.58px; content: attr(data-title); text-overflow: ellipsis; white-space: nowrap; pointer-events: none; }

.whatiuse-shared-detail__row-copy > span { overflow: hidden; color: var(--whatiuse-ink); font-size: 13.5px; font-weight: 520; text-overflow: ellipsis; white-space: nowrap; }

.whatiuse-shared-detail__row-copy small { color: var(--whatiuse-ink-tertiary); font-size: 11.5px; }

.whatiuse-shared-detail__status { padding: 2px 5px; border: 1px solid var(--whatiuse-border-subtle); border-radius: 4px; color: var(--whatiuse-ink-tertiary); font-size: 11px; }

.whatiuse-shared-detail__panel { min-width: 0; border-left: 1px solid var(--whatiuse-border-subtle); outline: 0; background: var(--whatiuse-surface); will-change: transform, opacity; }

.whatiuse-shared-detail__panel:focus-visible { box-shadow: inset 0 0 0 1px var(--whatiuse-focus); }

.whatiuse-shared-detail__toolbar { display: flex; justify-content: flex-end; gap: 1px; height: 40px; padding: 6px; border-bottom: 1px solid var(--whatiuse-border-subtle); }

.whatiuse-shared-detail__back { display: none; }

.whatiuse-shared-detail__content { padding: 22px; will-change: transform, opacity; }

.whatiuse-shared-detail__content h3 { margin: 0; font-size: 17px; font-weight: 580; letter-spacing: -0.025em; }

.whatiuse-shared-detail__meta { margin-top: 4px; color: var(--whatiuse-ink-tertiary); font-size: 11.5px; }

.whatiuse-shared-detail__content p { margin: 18px 0; color: var(--whatiuse-ink-secondary); font-size: 13px; line-height: 1.6; }

.whatiuse-shared-detail__content dl { display: grid; margin: 0; border-top: 1px solid var(--whatiuse-border-subtle); }

.whatiuse-shared-detail__content dl div { display: grid; grid-template-columns: 72px 1fr; padding: 8px 0; border-bottom: 1px solid var(--whatiuse-border-subtle); font-size: 11.5px; }

.whatiuse-shared-detail__content dt { color: var(--whatiuse-fg-subtle); }

.whatiuse-shared-detail__content dd { margin: 0; color: var(--whatiuse-fg-muted); }

@media (max-width: 760px) {
.whatiuse-shared-detail[data-open] { grid-template-columns: 1fr; }

.whatiuse-shared-detail[data-open] .whatiuse-shared-detail__list { display: none; }

.whatiuse-shared-detail__panel { border-left: 0; }

.whatiuse-shared-detail__back { display: inline-flex; margin-right: auto; }
}

@media (forced-colors: active) {
.whatiuse-shared-detail { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }

.whatiuse-shared-detail__row[aria-expanded="true"] { outline: 2px solid Highlight; outline-offset: -2px; }
}

.whatiuse-shared-detail__list {
  scrollbar-color: var(--whatiuse-scrollbar-thumb) transparent;
  scrollbar-width: thin;
}

.whatiuse-shared-detail__list::-webkit-scrollbar { width: 10px; height: 10px; }

.whatiuse-shared-detail__list::-webkit-scrollbar-track { background: transparent; }

.whatiuse-shared-detail__list::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: var(--whatiuse-scrollbar-thumb);
  background-clip: padding-box;
}

.whatiuse-shared-detail__list::-webkit-scrollbar-thumb:hover { background: var(--whatiuse-scrollbar-thumb-hover); background-clip: padding-box; }

:root[data-theme="dark"] .whatiuse-shared-detail__content dd { color: var(--whatiuse-ink); }

:root[data-theme="dark"] .whatiuse-shared-detail__content dt { color: var(--whatiuse-ink-tertiary); }

@media (forced-colors: active) {
.whatiuse-shared-detail__list { scrollbar-color: auto; }
}
}
